import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"WeCom (WeWork) Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/wecom.md","filePath":"integrations/channels/wecom.md","lastUpdated":1790952322000}'),r={name:"integrations/channels/wecom.md"};function i(s,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="wecom-wework-channel-configuration" tabindex="-1">WeCom (WeWork) Channel Configuration <a class="header-anchor" href="#wecom-wework-channel-configuration" aria-label="Permalink to &quot;WeCom (WeWork) Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to WeCom (企业微信) so it can talk with users in your organization&#39;s WeCom workspace, in direct messages and in group chats.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Admin access to the <a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom Admin Console</a>, to create the bot application.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-create-a-wecom-bot" tabindex="-1">1. Create a WeCom bot <a class="header-anchor" href="#_1-create-a-wecom-bot" aria-label="Permalink to &quot;1. Create a WeCom bot&quot;">​</a></h3><p>In the WeCom admin console:</p><ol><li>Log in to the <a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom Admin Console</a>.</li><li>Navigate to <strong>App Management</strong> &gt; <strong>Custom Apps</strong> or <strong>Bot Management</strong>.</li><li>Create a new bot application.</li><li>Note the <strong>Bot ID</strong> and <strong>Secret</strong> credentials.</li></ol><blockquote><p>Official docs: <a href="https://developer.work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom Open Platform</a> · <a href="https://developer.work.weixin.qq.com/document/path/91770" target="_blank" rel="noreferrer">WeCom Bot Documentation</a></p></blockquote><h3 id="_2-add-the-channel-in-memoh" tabindex="-1">2. Add the channel in Memoh <a class="header-anchor" href="#_2-add-the-channel-in-memoh" aria-label="Permalink to &quot;2. Add the channel in Memoh&quot;">​</a></h3><p>In Memoh:</p><ol><li>Open the bot&#39;s <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>WeCom</strong>.</li><li>Fill in <strong>Bot ID</strong> and <strong>Secret</strong>; set a custom <strong>WebSocket URL</strong> only if you need one.</li><li>Click <strong>Save and Enable</strong>.</li></ol><p>Once enabled, Memoh connects to WeCom over WebSocket and begins receiving messages.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Bot ID</strong></td><td>Yes</td><td>The WeCom bot identifier.</td></tr><tr><td><strong>Secret</strong></td><td>Yes</td><td>The bot&#39;s authentication credential.</td></tr><tr><td><strong>WebSocket URL</strong></td><td>No</td><td>Custom WebSocket endpoint; the default endpoint is used when empty.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Send <code>/help</code> to the bot in a direct message, or @mention it in a group chat with <code>/help</code>. The bot replies with its command list, which confirms the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>The bot also works in WeCom group chats: @mention it in a group to trigger a reply.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>Disable or remove the channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate credentials, update <strong>Bot ID</strong> / <strong>Secret</strong> in the same panel and save.</p>',21)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
